import {createRequire} from 'node:module';
import {readFile,writeFile,mkdir,readdir,copyFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const modulePath=process.argv[2]??'sharp',batch=Number(process.argv[3]??140),partial=process.argv[4]==='partial',sharp=createRequire(import.meta.url)(modulePath),root='art/review/web-v3',folder=process.argv[5]??root+'/results-calibration-20261026';
await mkdir(folder,{recursive:true});const previous=await readFile(folder+'/coverage.json','utf8').then(JSON.parse).catch(()=>null);if(previous&&previous.batch!==batch){await mkdir(folder+'/history-'+previous.batch,{recursive:true});for(const f of await readdir(folder,{withFileTypes:true}))if(f.isFile())await copyFile(folder+'/'+f.name,folder+'/history-'+previous.batch+'/'+f.name,1).catch(e=>{if(e.code!=='EEXIST')throw e;});}
const reports=[],sha=async p=>createHash('sha256').update(await readFile(p)).digest('hex');
