 for(const[n,rect]of boxes.entries()){const[x,y,w,h]=rect,cw=tall?941:1672,ch=tall?1672:941,region={left:Math.round(x/cw*width),top:Math.round(y/ch*height),width:Math.round(w/cw*width),height:Math.round(h/ch*height)};for(const[i,input]of inputs.entries())layers.push({input:await sharp(input).extract(region).resize(650,200,{fit:'contain',background:'#10151d'}).png().toBuffer(),left:i*658,top:n*208});}
